Looking at the demos more carefully, the pattern becomes clearer: cells turn to 4 when they're at intersection points where **at least two opposite neighbors in one direction exist** (top+bottom OR left+right, diagonally jumping over cells).

```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]

            # Check for same-value cells in vertical line (same column)
            has_above = False
            has_below = False
            for i in range(r - 1, -1, -1):
                if grid[i][c] == val:
                    has_above = True
                    break
            for i in range(r + 1, rows):
                if grid[i][c] == val:
                    has_below = True
                    break

            # Check for same-value cells in horizontal line (same row)
            has_left = False
            has_right = False
            for i in range(c - 1, -1, -1):
                if grid[r][i] == val:
                    has_left = True
                    break
            for i in range(c + 1, cols):
                if grid[r][i] == val:
                    has_right = True
                    break

            # If aligned in vertical OR horizontal direction, mark as 4
            if (has_above or has_below) or (has_left or has_right):
                output[r][c] = 4

    return output
